<?php
require_once __DIR__.'/includes/auth.php'; require_role(['admin','hiring_manager']);
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check(); $id=(int)($_POST['id']??0); $status=$_POST['status']??'present'; $allowed=['present','late','absent','half_day','on_leave','holiday','incomplete']; if(in_array($status,$allowed,true)){ $s=db()->prepare('UPDATE attendance_records SET status=?,approved_by=?,approved_at=NOW() WHERE id=?'); $s->execute([$status,$_SESSION['user_id'],$id]); audit('attendance_update','attendance',$id); flash('success','Attendance record updated.'); } header('Location: attendance-admin.php'); exit; }
$from=$_GET['from']??date('Y-m-01'); $to=$_GET['to']??date('Y-m-d'); $s=db()->prepare('SELECT a.*,e.employee_number,u.name,e.job_title FROM attendance_records a JOIN employees e ON e.id=a.employee_id LEFT JOIN users u ON u.id=e.user_id WHERE a.work_date BETWEEN ? AND ? ORDER BY a.work_date DESC,u.name'); $s->execute([$from,$to]); $rows=$s->fetchAll(); $pageTitle='Attendance Review'; include __DIR__.'/includes/header.php'; ?>
<div class="page-heading"><div><span class="eyebrow">Admin and manager tools</span><h1>Attendance review</h1><p>Review clock records, correct statuses, and approve exceptions.</p></div></div><?php if($msg=take_flash()): ?><div class="toast success"><?=htmlspecialchars($msg)?></div><?php endif; ?><form class="filter-bar" method="get"><label>From<input type="date" name="from" value="<?=htmlspecialchars($from)?>"></label><label>To<input type="date" name="to" value="<?=htmlspecialchars($to)?>"></label><button class="button primary">Review</button></form><div class="card"><div class="table-wrap"><table><thead><tr><th>Employee</th><th>Date</th><th>In</th><th>Out</th><th>Hours</th><th>Status</th><th>Save</th></tr></thead><tbody><?php foreach($rows as $row): ?><tr><td><strong><?=htmlspecialchars($row['name']??'Unlinked')?></strong><small class="muted"><?=htmlspecialchars($row['employee_number']??'')?></small></td><td><?=htmlspecialchars($row['work_date'])?></td><td><?= $row['clock_in']?date('g:i A',strtotime($row['clock_in'])):'—' ?></td><td><?= $row['clock_out']?date('g:i A',strtotime($row['clock_out'])):'—' ?></td><td><?= $row['worked_minutes']?number_format($row['worked_minutes']/60,1):'—' ?></td><td><form method="post" class="inline-form" id="att-<?=$row['id']?>"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="id" value="<?=$row['id']?>"><select name="status"><?php foreach(['present','late','absent','half_day','on_leave','holiday','incomplete'] as $status): ?><option <?=$row['status']===$status?'selected':''?>><?=$status?></option><?php endforeach; ?></select></form></td><td><button class="button small secondary" type="submit" form="att-<?=$row['id']?>">Save</button></td></tr><?php endforeach; ?></tbody></table></div></div><?php include __DIR__.'/includes/footer.php'; ?>
